WITH p AS (SELECT %s::date dfrom,%s::date dto,coalesce(%s::text,'') ma_kh,coalesce(%s::text,'') ma_vt,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid),g AS (SELECT h.ma_kh,d.ma_vt,sum(d.so_luong) sl_giao_bu FROM public.ph96 h JOIN public.ct96 d ON d.stt_rec=h.stt_rec CROSS JOIN s WHERE s.ok IS NOT NULL AND h.ngay_ct BETWEEN s.dfrom AND s.dto AND h.ma_gd=10 AND(s.ma_kh='' OR h.ma_kh=ANY(string_to_array(s.ma_kh,',')))AND(s.ma_vt='' OR d.ma_vt=ANY(string_to_array(s.ma_vt,',')))AND(s.unrestricted OR h.ma_dvcs=ANY(string_to_array(s.bs,',')))AND(d.ma_kho='' OR s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho k WHERE k.ma_kho=d.ma_kho AND k.ma_dvcs=ANY(string_to_array(s.bs,',')))) GROUP BY h.ma_kh,d.ma_vt),r AS (SELECT h.ma_kh,d.ma_vt,sum(d.so_luong) sl_ng_nhan_lai FROM public.ph66 h JOIN public.ct66 d ON d.stt_rec=h.stt_rec CROSS JOIN s WHERE s.ok IS NOT NULL AND h.ngay_ct BETWEEN s.dfrom AND s.dto AND h.ma_gd=1 AND(s.ma_kh='' OR h.ma_kh=ANY(string_to_array(s.ma_kh,',')))AND(s.ma_vt='' OR d.ma_vt=ANY(string_to_array(s.ma_vt,',')))AND(s.unrestricted OR h.ma_dvcs=ANY(string_to_array(s.bs,',')))AND(d.ma_kho='' OR s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho k WHERE k.ma_kho=d.ma_kho AND k.ma_dvcs=ANY(string_to_array(s.bs,',')))) GROUP BY h.ma_kh,d.ma_vt),q AS (SELECT coalesce(g.ma_kh,r.ma_kh) ma_kh,coalesce(g.ma_vt,r.ma_vt) ma_vt,coalesce(g.sl_giao_bu,0) sl_giao_bu,coalesce(r.sl_ng_nhan_lai,0) sl_ng_nhan_lai FROM g FULL JOIN r ON r.ma_kh=g.ma_kh AND r.ma_vt=g.ma_vt) SELECT q.ma_kh,k.ten_kh,q.ma_vt,v.ten_vt,q.sl_giao_bu,q.sl_ng_nhan_lai,q.sl_giao_bu-q.sl_ng_nhan_lai sl_con_treo,count(*) OVER() total FROM q LEFT JOIN public.dmkh k ON k.ma_kh=q.ma_kh LEFT JOIN public.dmvt v ON v.ma_vt=q.ma_vt ORDER BY q.ma_kh,q.ma_vt LIMIT(SELECT lim FROM p);
